    "sourceRepo": "indranilbanerjee/digital-marketing-pro",
    "sourceCommit": "fa4ccd0a4afc1b902ef8de8d297b180aa148d46a",
    "sourcePath": "agents/pr-outreach.md",
    "license": "MIT"
